changeSet.sql:
GRANT SELECT, INSERT ON historial_variable TO app_backend;
GRANT USAGE, SELECT ON SEQUENCE historial_variable_id_historial_seq TO app_backend;

GRANT SELECT, INSERT ON estado_ambiental TO app_backend;
GRANT USAGE, SELECT ON SEQUENCE estado_ambiental_id_estado_seq TO app_backend;

GRANT SELECT, INSERT ON estadistica_ambiental TO app_backend;
GRANT USAGE, SELECT ON SEQUENCE estadistica_ambiental_id_estadistica_seq TO app_backend;

GRANT SELECT ON historial_variable TO app_readonly;
GRANT SELECT ON estado_ambiental TO app_readonly;
GRANT SELECT ON estadistica_ambiental TO app_readonly;

rollback.sql:
REVOKE SELECT, INSERT ON historial_variable FROM app_backend;
REVOKE USAGE, SELECT ON SEQUENCE historial_variable_id_historial_seq FROM app_backend;

REVOKE SELECT, INSERT ON estado_ambiental FROM app_backend;
REVOKE USAGE, SELECT ON SEQUENCE estado_ambiental_id_estado_seq FROM app_backend;

REVOKE SELECT, INSERT ON estadistica_ambiental FROM app_backend;
REVOKE USAGE, SELECT ON SEQUENCE estadistica_ambiental_id_estadistica_seq FROM app_backend;

REVOKE SELECT ON historial_variable FROM app_readonly;
REVOKE SELECT ON estado_ambiental FROM app_readonly;
REVOKE SELECT ON estadistica_ambiental FROM app_readonly;
